{"content": "#!/usr/bin/env python3
"""Independent f table built from MISSION section 2 recurrence ALONE
(mex over POSITIVE integers, exactly as written), cross-checked against the
solver; then direct checks of derivation steps 1-3 of (FR).
"""
import subprocess, sys

RMAX = int(sys.argv[1]) if len(sys.argv) > 1 else 250
QMAX = int(sys.argv[2]) if len(sys.argv) > 2 else 700

# ---- build f from scratch, memoized, q<=QMAX, r<=RMAX ----
from functools import lru_cache

@lru_cache(maxsize=None)
def f(q, r):
    if q < 0 or r < 0:
        raise ValueError
    if r > q:
        return f(q, q)
    if q == 0 and r == 0:
        return 1   # mex over positive ints of empty set
    if q >= 1 and f(q - 1, r) < q:
        return f(q - 1, r)
    S = set()
    for a in range(0, q):
        S.add(f(a, r))
    for b in range(0, r):
        S.add(f(q, b))
    m = 1
    while m in S:
        m += 1
    return m

F = [[f(q, r) for r in range(0, RMAX + 1)] for q in range(0, QMAX + 1)]
sys.setrecursionlimit(100000)

# ---- cross-check against solver ----
out = subprocess.run(["./solver", "table", "--rmax", str(RMAX), "--qmax", str(QMAX)],
                     capture_output=True, text=True, check=True).stdout
G = [[int(v) for v in ln.split()] for ln in out.splitlines() if ln.strip() and not ln.startswith("#")]
ndiff = 0
for q in range(0, QMAX + 1):
    for r in range(0, RMAX + 1):
        if F[q][r] != G[q][r]:
            ndiff += 1
            if ndiff < 5:
                print("solver/rebuild mismatch", q, r, F[q][r], G[q][r])
print("rebuild vs solver: %d cells, %d mismatches" % ((QMAX + 1) * (RMAX + 1), ndiff))

def fval(q, r):
    return F[q][r] if r <= q else F[q][q]

# ---- derivation step 1 & 3 checks at every reached (r,a) ----
def B(c, x):
    q = c + x
    v = fval(q, c)
    return v - q if v >= q else None

bad1 = bad2 = bad3 = steps = 0
for r in range(1, RMAX + 1):
    for a in range(0, QMAX - r + 1):
        q = r + a
        L = B(r, a)
        # step 1: f(q,r) >= q at reached a
        if L is None:
            # reached iff all previous L>=1; if this is the first None, previous must be a 0
            bad1 += 1
            if bad1 < 5: print("step1: f(q,r)<q at reached? r=%d a=%d" % (r, a))
            break
        if L < 0:
            bad1 += 1
            if bad1 < 5: print("step1 fail", r, a, L)
            break
        S = set()
        for x in range(0, q):
            S.add(fval(x, r))
        for b in range(0, r):
            S.add(fval(q, b))
        # step 3: {1,...,q-1} subset S  and  mex_{>=1}(S) = f(q,r)
        if not set(range(1, q)).issubset(S):
            bad2 += 1
            if bad2 < 5: print("step3 subset fail r=%d a=%d q=%d" % (r, a, q))
        m = 1
        while m in S:
            m += 1
        if m != fval(q, r):
            bad3 += 1
            if bad3 < 5: print("mex identity fail r=%d a=%d" % (r, a))
        # shift identity: f(q,r) = q + mex_{>=0}(S_q)
        Sq = set(s - q for s in S if s >= q)
        m0 = 0
        while m0 in Sq:
            m0 += 1
        if q + m0 != fval(q, r):
            bad3 += 1
            if bad3 < 5: print("shift fail r=%d a=%d" % (r, a))
        steps += 1
        if L == 0:
            break   # row terminates
print("reached steps checked: %d ; step1 fails %d ; step3-subset fails %d ; mex/shift fails %d"
      % (steps, bad1, bad2, bad3))
